window.NOTES={"version":44,"chapters":[{"number":1,"title":"信息技术与计算机文化","summary":"计算机发展、信息表示、硬件、软件与计算机系统的基础概念。","sections":[{"id":"1.1","title":"信息与信息技术"},{"id":"1.2","title":"计算机技术概论"},{"id":"1.3","title":"计算机中信息的表示"},{"id":"1.4","title":"计算机系统"},{"id":"1.5","title":"微型计算机系统"}]},{"number":2,"title":"Windows 10 操作系统","summary":"操作系统特征、Windows界面、文件管理、系统设置与维护。","sections":[{"id":"2.1","title":"操作系统概述"},{"id":"2.2","title":"Windows 10 基础"},{"id":"2.3","title":"文件和文件夹管理"},{"id":"2.4","title":"控制面板"},{"id":"2.5","title":"Windows 10 的系统维护"},{"id":"2.6","title":"Windows 10 的实用工具"}]},{"number":3,"title":"字处理软件 Word 2016","summary":"文档编辑、格式排版、表格、图文混排与长文档功能。","sections":[{"id":"3.1","title":"使用 Office 2016 应用程序"},{"id":"3.2","title":"Word 2016 的基本操作"},{"id":"3.3","title":"文档格式化与排版"},{"id":"3.4","title":"表格制作"},{"id":"3.5","title":"图文混排"},{"id":"3.6","title":"文档的保护与打印"},{"id":"3.7","title":"Word 2016 的高级应用"}]},{"number":4,"title":"电子表格系统 Excel 2016","summary":"工作表操作、公式与函数、格式化、数据处理和图表。","sections":[{"id":"4.1","title":"Excel 2016 概述"},{"id":"4.2","title":"Excel 2016 的基本操作"},{"id":"4.3","title":"Excel 公式与函数"},{"id":"4.4","title":"格式化工作表"},{"id":"4.5","title":"数据处理"},{"id":"4.6","title":"使用图表"}]},{"number":5,"title":"演示文稿软件 PowerPoint 2016","summary":"幻灯片组织、外观、动画、切换与放映设置。","sections":[{"id":"5.1","title":"PowerPoint 2016 基础"},{"id":"5.2","title":"幻灯片页面设计"},{"id":"5.3","title":"幻灯片页面外观的修饰"},{"id":"5.4","title":"动画效果和动作设置"},{"id":"5.5","title":"播放和打印演示文稿"},{"id":"5.6","title":"演示文稿的其他功能"}]},{"number":6,"title":"计算机网络及网页制作","summary":"网络结构、Internet应用、HTML、网页与信息检索。","sections":[{"id":"6.1","title":"计算机网络概述"},{"id":"6.2","title":"计算机网络系统"},{"id":"6.3","title":"Internet 基础和应用"},{"id":"6.4","title":"网页、网页制作及 HTML 简介"},{"id":"6.5","title":"信息检索"}]},{"number":7,"title":"数字多媒体技术基础","summary":"多媒体特征、媒体元素、图像格式、颜色和视频。","sections":[{"id":"7.1","title":"数字多媒体技术概述"},{"id":"7.2","title":"数字多媒体系统组成及常用软件"},{"id":"7.3","title":"常用多媒体制作软件"}]},{"number":8,"title":"信息安全","summary":"安全属性、恶意软件、防火墙、密码技术和信息伦理。","sections":[{"id":"8.1","title":"信息安全概述"},{"id":"8.2","title":"计算机病毒"},{"id":"8.3","title":"防火墙"},{"id":"8.4","title":"Windows 10 操作系统安全"},{"id":"8.5","title":"信息伦理"}]},{"number":9,"title":"信息技术前沿","summary":"虚拟现实、云计算、物联网、区块链与人工智能。","sections":[{"id":"9.1","title":"虚拟现实和增强现实"},{"id":"9.2","title":"云计算和高性能计算"},{"id":"9.3","title":"物联网技术"},{"id":"9.4","title":"大数据技术"},{"id":"9.5","title":"区块链技术"},{"id":"9.6","title":"人工智能"},{"id":"9.7","title":"量子通信"},{"id":"9.8","title":"元宇宙"}]},{"number":10,"title":"数据库技术基础","summary":"关系数据库、数据库管理系统、关系运算、SQL与NoSQL。","sections":[{"id":"10.1","title":"数据库技术基础"},{"id":"10.2","title":"数据库管理系统"},{"id":"10.3","title":"数据库设计与 NoSQL"}]},{"number":11,"title":"计算思维","summary":"计算思维、算法表示、算法特征和基本控制结构。","sections":[{"id":"11.1","title":"计算思维"},{"id":"11.2","title":"计算思维与算法"},{"id":"11.3","title":"算法的控制结构"},{"id":"11.4","title":"面向对象程序设计"},{"id":"11.5","title":"基础算法设计思想"}]}],"notes":[{"q":3,"chapter":11,"section":"11.1","type":"单选","topic":"计算思维","title":"计算思维不是计算机科学家的专属思维","trigger":"真题直接考查计算思维的适用范围和常见方法。","conclusion":"计算思维是一套可用于多学科问题求解的思维方法，并非计算机科学家专属。","points":["常见过程包括分解、抽象、模式识别和算法设计。","它可以借助计算机，也可以先在纸面上形成问题模型。","医学、管理、工程和日常决策都可使用计算思维。","抽象保留与目标相关的要素、忽略暂时无关细节；自动化把明确的过程交给机器执行。计算思维是人的问题求解方式，不只是机械操作计算机。"],"boundary":"计算思维不等于会操作软件，也不等于任何问题都必须写程序。","id":"y2025q4","sources":[{"year":2023,"q":3,"type":"单选"},{"year":2025,"q":4,"type":"单选"},{"year":2021,"q":23,"type":"多选","page":4}],"keys":["2023-3","2025-4","2021-23"]},{"q":42,"chapter":11,"section":"11.1","type":"填空","topic":"算法表示","title":"伪代码用接近自然语言的结构描述算法","trigger":"题目要求填写一种不依赖具体编程语言的算法表示方法。","conclusion":"伪代码用结构化、近似程序的文字表达算法逻辑，不要求遵守某门语言的完整语法。","points":["伪代码应清楚体现输入、处理、输出和控制结构。","它便于在编码前讨论算法思想。","流程图也可表示算法，但形式是图形符号和流程线。","自然语言、伪代码、流程图可描述算法步骤；E-R图描述实体及联系，不是算法流程图。"],"boundary":"伪代码没有唯一语法，却仍应保持关键词、缩进和变量含义一致。","id":"y2026q42","sources":[{"year":2026,"q":42,"type":"填空"},{"year":2022,"q":5,"type":"单选"}],"keys":["2026-42","2022-5"]},{"q":3,"target":null,"page":1,"chapter":11,"section":"11.2","topic":"队列","title":"队列先进先出，多队列交错不能打乱各自顺序","conclusion":"队列从队尾加入、从队头取出，遵循FIFO；多个队列可以交替出队，但各自内部先后顺序保持不变。","points":["车道一按A、B、C、D排队，车道二按E、F、G、H排队，每次只能放行某车道队首。","ABEFCDGH是合法交错；AFEBCDGH中F先于E，违反第二队列顺序。","判断一串输出是否合法，可分别抽出属于每个队列的元素，检查相对次序是否保持。","栈是后进先出LIFO，操作限制与队列不同。"],"boundary":"队列先后只约束本队列；不能据此断言A必定先于另一队列的E。","type":"单选","trigger":"围绕队列的识别、应用与易错边界整理。","id":"y2021q3","sources":[{"year":2021,"q":3,"type":"单选"}],"keys":["2021-3"]},{"q":33,"target":null,"chapter":11,"section":"11.2","topic":"算法复杂度","title":"时间复杂度与空间复杂度不必同向变化","conclusion":"时间复杂度描述运算量随输入规模增长的趋势；空间复杂度描述所需存储空间的增长趋势，两者没有必然正比例关系。","points":["同一问题可用缓存结果换取更少重复计算，这是以空间换时间。","逐个扫描求和通常需O(n)时间和O(1)额外空间。","创建前缀和数组预处理需O(n)时间和空间，之后每次区间求和可O(1)完成。"],"boundary":"复杂度不是一次运行的秒数或某台电脑的内存容量；应说明输入规模与是否统计额外空间。","type":"判断","trigger":"从算法复杂度的判断与应用整理。","id":"y2022q33","sources":[{"year":2022,"q":33,"type":"判断"}],"keys":["2022-33"]},{"q":4,"chapter":11,"section":"11.2","type":"单选","topic":"算法特征与评价","title":"算法必须确定、可行、有限并产生输出","trigger":"真题从输出、可行性和实现前评价考查算法的基本特征。","conclusion":"算法可以没有外部输入，但至少有一个输出；每一步应确定、可行，并在有限步骤后结束，也可以在编码前分析正确性与复杂度。","points":["确定性要求每一步含义明确，可行性要求操作能在有限资源下执行。","时间复杂度和空间复杂度可依据算法结构分析。","程序是算法的一种实现，测试实现不能代替算法论证。","算法允许零个或多个输入，但必须有一个或多个输出；“输入必须有、输出可以无”把条件写反。","辗转相除法中，若本轮a除以b余数为0，最大公约数就是当前除数b；首轮整除时也适用。输入域和终止条件必须明确。"],"boundary":"伪代码仍需转成可执行程序；“程序跑起来”也不等于算法正确或高效。","id":"y2026q6","sources":[{"year":2024,"q":4,"type":"单选"},{"year":2025,"q":5,"type":"单选"},{"year":2026,"q":6,"type":"单选"},{"year":2022,"q":6,"type":"单选"}],"keys":["2024-4","2025-5","2026-6","2022-6"]},{"q":33,"target":null,"page":5,"chapter":11,"section":"11.3","topic":"先执行后判断","title":"流程图要按箭头追踪，判断位置决定是否先执行一轮","conclusion":"本例先执行S=S+k，再令k=k+3，最后判断k＜10；从S=0、k=1开始，累加1、4、7后输出12。判断位置、条件方向和变量更新顺序要一起追踪。","points":["每轮记录执行前的k、累加后的S、更新后的k以及继续条件真假，按流程箭头实际经过的顺序执行。","第一轮S=1、k=4；第二轮S=5、k=7；第三轮S=12、k=10，条件不成立退出，因此10未被累加。","把继续条件改成k≤10，会再累加10，随后k变为13，输出变为22；边界等号是否存在会改变执行次数。","后测试循环先执行循环体，至少执行一次；先测试循环先判断，初始条件不成立时可能执行0次。","例如仍取S=0、k=1，但边界设为1：本例后测试写法会先加1再退出；将条件移到循环体之前则一次也不加。","S应在循环外初始化；循环变量必须按规则推进，使退出条件最终能满足。赋值S=S+k是用旧值计算后写回，不是代数恒等式。"],"boundary":"判断框移到循环体前后、把＜改成≤、或把k的更新提前，都可能改变结果；箭头上的“是/否”通向哪里也必须与条件一起阅读。","type":"填空","trigger":"围绕先执行后判断的识别、应用与易错边界整理。","id":"y2021q33","sources":[{"year":2021,"q":33,"type":"填空"}],"keys":["2021-33"],"comparison":{"headers":["条件与结构","累加项","输出"],"rows":[["本例后测试，k＜10","1、4、7","12"],["本例后测试，k≤10","1、4、7、10","22"],["边界1，后测试","1","1"],["边界1，先测试","无","0"]]}},{"q":43,"target":null,"chapter":11,"section":"11.3","topic":"累加循环","title":"先初始化，再累加，再推进循环变量","conclusion":"S=0、i=1；当i≤10时执行S=S+i、i=i+1，最终S为55。","points":["S保存累计结果，i保存当前加数；二者职责不同。","S应在循环外初始化，否则每轮重置会丢失历史结果。","最后一次相加使用i=10，之后i变成11，条件不成立才退出。","可用等差数列1+…+10=10×11÷2核验，不替代逐步理解循环。"],"boundary":"S=S+i是赋值更新，不是代数恒等式；把推进语句提前会改变被累加的数列。","type":"填空","trigger":"从累加循环的判断与应用整理。","id":"y2022q43","sources":[{"year":2022,"q":43,"type":"填空"}],"keys":["2022-43"]},{"q":69,"chapter":11,"section":"11.3","type":"分析","topic":"循环计数","title":"计数循环要同时检查初值、边界、条件和累加器","trigger":"两道连续分析题补全处理45名学生的循环条件，并解释不及格人数累加语句。","conclusion":"若i从1开始逐次加1，处理45人可写i\u003c=45；满足不及格条件时执行C=C+1，且C应在循环前初始化为0。","points":["循环边界取决于计数器初值与下标体系。","赋值号表示把右侧新值写回左侧变量。","只有分支条件成立时才增加不及格计数。"],"boundary":"若数组从0开始可能写i\u003c45；C未初始化或在循环内反复置0都会导致错误。","id":"y2023q69","sources":[{"year":2023,"q":69,"type":"分析"},{"year":2023,"q":70,"type":"分析"}],"keys":["2023-69","2023-70"]},{"q":25,"chapter":11,"section":"11.3","type":"多选","topic":"控制结构","title":"顺序、分支和循环可以相互嵌套","trigger":"两道题综合判断三种基本控制结构的含义和嵌套关系。","conclusion":"顺序按先后执行，分支按条件选择路径，循环在终止条件控制下重复；三者可以结构化嵌套。","points":["分支可表达条件成立执行A，否则执行B。","循环由循环体和循环控制条件构成。","结构化组合有助于保持流程可追踪。"],"boundary":"“外层是顺序结构”不意味着内部不能含分支或循环。","id":"y2026q5","sources":[{"year":2025,"q":25,"type":"多选"},{"year":2026,"q":5,"type":"单选"}],"keys":["2025-25","2026-5"]},{"q":24,"chapter":11,"section":"11.4","type":"多选","topic":"面向对象","title":"面向对象用类、对象、封装和消息组织程序","trigger":"题目要求识别面向对象程序设计的基本思想与方法。","conclusion":"面向对象以类和对象为核心，通过封装组织数据与操作，并通过消息或方法调用建立对象协作。","points":["类描述一类对象的共同属性和行为。","对象是类的实例。","封装把数据及其操作组织在一起并控制访问。","类是共同属性和行为的抽象，对象是类的实例；封装控制内部细节的访问，继承复用或扩展类型，多态使同一接口出现不同实现。"],"boundary":"面向对象不是结构化程序设计的同义词；二者可以在同一系统中结合使用。","id":"y2025q24","sources":[{"year":2025,"q":24,"type":"多选"},{"year":2022,"q":23,"type":"多选"}],"keys":["2025-24","2022-23"]},{"q":69,"chapter":11,"section":"11.5","type":"分析","topic":"冒泡排序","title":"一趟升序冒泡把最大值推到右端","trigger":"两道连续分析题先补比较条件，再追踪一趟排序结果。","conclusion":"本例从左向右进行升序冒泡：仅在a[j]＞a[j+1]时交换相邻元素，一趟后本趟最大值到右端；8、5、2、9、7、3的一趟结果是5、2、8、7、3、9。","points":["每一步先比较当前相邻元素，再决定是否交换；不能不看数值就按固定脚本交换。","第一次完整从左向右扫描n个元素需比较n−1对；完成一趟通常只保证一个最大值就位，不代表整个序列有序。","后续趟可缩短尚未排序的范围；有提前结束标记的版本在某一整趟没有交换时即可结束。","保持扫描方向不变，把交换条件改为左值小于右值可得到降序；若从右向左扫描，升序一趟通常是把最小值移到左端，因此要先看循环方向。","相等元素不交换，可保持它们原有的相对次序；判断稳定性应给重复值附上身份，如3甲与3乙。","一般冒泡排序的平均及最坏时间复杂度为O(n²)，额外空间为O(1)；有提前结束判断时，已经有序的输入只需一趟扫描。"],"boundary":"“一趟冒泡”的结果取决于扫描方向和比较条件，不能只背最大值到右端；一趟结束与全表有序是两个状态。","id":"y2024q69","sources":[{"year":2024,"q":69,"type":"分析"},{"year":2024,"q":70,"type":"分析"}],"keys":["2024-69","2024-70"],"comparison":{"headers":["本例操作","保证什么","不保证什么"],"rows":[["一次相邻比较","纠正这一对的逆序关系","整个序列已排序"],["一趟从左到右升序扫描","未排序范围最大值到右端","其余元素全部有序"],["整趟没有交换","当前范围已经有序","所有实现都自动提前结束"]]}}],"sourceCount":460,"years":[2020,2021,2022,2023,2024,2025,2026]};
